#!/usr/bin/env tsx
import Fastify from 'fastify';
import fastifyStatic from '@fastify/static';
import fastifyWebsocket from '@fastify/websocket';
import cors from '@fastify/cors';
import rateLimit from '@fastify/rate-limit';
import {
  serializerCompiler,
  validatorCompiler,
  ZodTypeProvider
} from 'fastify-type-provider-zod';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { existsSync } from 'fs';
import { Prisma } from '@prisma/client';
import { registerRoutes } from '@/server/routes';
import { registerWebSocket, activeSessions } from '@/server/websocket';
import { registerShellRoute } from '@/server/routes/shell';
import { authPlugin } from '@/server/plugins/auth';
import { setupGracefulShutdown } from '@/server/utils/shutdown';
import {
  NotFoundError,
  UnauthorizedError,
  ForbiddenError,
  ValidationError as CustomValidationError,
  buildErrorResponse
} from '@/server/utils/error';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

export async function createServer() {
  const fastify = Fastify({
    logger: process.env.NODE_ENV === 'production'
      ? {
          level: process.env.LOG_LEVEL || 'info',
          transport: {
            targets: [
              // Console output (for Docker, PM2, systemd)
              {
                target: 'pino/file',
                options: { destination: 1 }, // stdout
                level: 'info'
              },
              // File output
              {
                target: 'pino/file',
                options: {
                  destination: process.env.LOG_FILE || './logs/app.log',
                  mkdir: true
                },
                level: process.env.LOG_LEVEL || 'info'
              }
            ]
          }
        }
      : {
          // Development: pretty-print to console + log file
          level: process.env.LOG_LEVEL || 'info',
          transport: {
            targets: [
              // Pretty console output
              {
                target: 'pino-pretty',
                options: {
                  colorize: true,
                  translateTime: 'HH:MM:ss Z',
                  ignore: 'pid,hostname'
                },
                level: process.env.LOG_LEVEL || 'info'
              },
              // File output (plain JSON)
              {
                target: 'pino/file',
                options: {
                  destination: process.env.LOG_FILE || './logs/app.log',
                  mkdir: true
                },
                level: process.env.LOG_LEVEL || 'info'
              }

/**
 * agent-cli-sdk - TypeScript SDK for AI CLI orchestration
 * @packageDocumentation
 */

// Adapters
export { ClaudeAdapter } from './claude';
export { CodexAdapter } from './codex';
export { CursorAdapter } from './cursor';
export { GeminiAdapter } from './gemini';

// Import adapters for use in getAdapter helper
import { ClaudeAdapter } from './claude';
import { CodexAdapter } from './codex';
import { CursorAdapter } from './cursor';
import { GeminiAdapter } from './gemini';

// Adapter types
export type {
  ClaudeOptions,
  ClaudeConfig,
  ClaudeStreamEvent,
} from './claude';

export type {
  CodexOptions,
  CodexConfig,
  CodexStreamEvent,
} from './codex';

export type {
  CursorConfig,
  CursorOptions,
} from './cursor';

export type {
  GeminiConfig,
  GeminiOptions,
} from './gemini';

// Shared types
export type {
  ExecutionOptions,
  ExecutionResponse,
  StreamEvent,
  OutputData,
  TokenUsage,
  ModelUsage,
  ActionLog,
  ValidationResult,
} from './shared/types';

// Errors
export {
  AgentSDKError,
  ValidationError,
  CLINotFoundError,
  AuthenticationError,
  ExecutionError,
  TimeoutError,
  ParseError,
  SessionError,
} from './shared/errors';

// JSON utilities
export {
  extractJSON,
  parseJSONL,
  safeJSONParse,
} from './shared/json-parser';

// Claude event types and guards
export type {
  FileHistorySnapshotData,
  FileHistorySnapshotEvent,
  ThinkingMetadata,
  MessageContent,
  TextContent,
  ThinkingContent,
  ToolUseContent,
  ToolResultContent,
  ClaudeTokenUsage,
  ClaudeMessage,
  ToolUseResult,
  UserMessageData,
  UserMessageEvent,
  AssistantMessageData,
  AssistantMessageEvent,
} from './claude/events';

export {
  isClaudeEvent,
  isFileHistorySnapshotEvent,
  isUserMessageEvent,
  isAssistantMessageEvent,
} from './claude/events';

// Codex event types and guards
export type {
  CodexUsage,
